import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BPaanrMb.js";const m=JSON.parse('{"title":"Apollo Lite resources","description":"Apollo Lite models, perception, planning, control, calibration, engineering tools and WheelOS data/map service entry points.","frontmatter":{"title":"Apollo Lite resources","description":"Apollo Lite models, perception, planning, control, calibration, engineering tools and WheelOS data/map service entry points.","status":"Repository fact","content_type":"resources","keywords":["Apollo Lite","perception models","planning and control","calibration","engineering tools"]},"headers":[],"relativePath":"en/resources/index.md","filePath":"en/resources/index.md","lastUpdated":1794551845000}'),n={name:"en/resources/index.md"};function i(l,e,d,s,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="apollo-lite-resources" tabindex="-1">Apollo Lite resources <a class="header-anchor" href="#apollo-lite-resources" aria-label="Permalink to &quot;Apollo Lite resources&quot;">​</a></h1><p>This page organizes the models, algorithms, tools, datasets and map services used for development, integration, calibration and validation around <a href="https://github.com/wheelos/apollo-lite" target="_blank" rel="noreferrer">Apollo Lite</a>. Resources link primarily to source, configuration and documentation. Services that are not public are marked as pending rather than presented as downloadable assets.</p><p><code>Implemented</code> means that source or configuration exists. It does not mean that the capability has completed production validation for every vehicle or operating environment.</p><h2 id="find-resources-by-task" tabindex="-1">Find resources by task <a class="header-anchor" href="#find-resources-by-task" aria-label="Permalink to &quot;Find resources by task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Entry point</th></tr></thead><tbody><tr><td>Prepare perception models and inference configuration</td><td><a href="#models-and-inference">Models and inference</a></td></tr><tr><td>Enable ground, lane or obstacle perception</td><td><a href="#perception-packages">Perception packages</a></td></tr><tr><td>Develop precision parking and mapless planning</td><td><a href="#planning-and-parking">Planning and parking</a></td></tr><tr><td>Calibrate vehicle dynamics and longitudinal/lateral control</td><td><a href="#calibration-and-control">Calibration and control</a></td></tr><tr><td>Record, replay, visualize and debug</td><td><a href="#engineering-tools">Engineering tools</a></td></tr><tr><td>Obtain vehicle data or generate maps</td><td><a href="#wheelos-data-services">WheelOS data services</a> · <a href="#wheelos-map-services">WheelOS map services</a></td></tr></tbody></table><h2 id="models-and-inference" tabindex="-1">Models and inference <a class="header-anchor" href="#models-and-inference" aria-label="Permalink to &quot;Models and inference&quot;">​</a></h2><p>Download the associated <code>conf</code>, sensor parameters and model version with each model. Replacing a weight file alone is not a valid deployment procedure.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Apollo Lite use</th><th>Contents</th><th>Entry</th></tr></thead><tbody><tr><td>Camera obstacle models</td><td>Camera obstacle detection</td><td>YOLO, YOLOv4, SMOKE detectors and postprocessing</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera" target="_blank" rel="noreferrer">Camera perception</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models" target="_blank" rel="noreferrer">Model configuration</a></td></tr><tr><td>Camera lane models</td><td>Lane detection and calibration</td><td>Lane, DarkSCNN and Denseline postprocessing</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/lane" target="_blank" rel="noreferrer">Lane module</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/lane_detector" target="_blank" rel="noreferrer">Lane model</a></td></tr><tr><td>Traffic-light models</td><td>Detection and recognition</td><td>Detection, recognition and production configuration</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/traffic_light_detection" target="_blank" rel="noreferrer">Detection configuration</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/camera/models/traffic_light_recognition" target="_blank" rel="noreferrer">Recognition configuration</a></td></tr><tr><td>LiDAR obstacle models</td><td>Point-cloud detection and segmentation</td><td>CNNSEG, NCUT, center-based and spatio-temporal ground detection</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar" target="_blank" rel="noreferrer">LiDAR perception</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/production/data/perception/lidar/models" target="_blank" rel="noreferrer">LiDAR model configuration</a></td></tr><tr><td>Camera semantic segmentation</td><td>Semantic segmentation inference</td><td>SegFormer ONNX/TensorRT export and build tools</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/camera_semantic_segmentation" target="_blank" rel="noreferrer">camera_semantic_segmentation</a></td></tr></tbody></table><p>Recommended model metadata: sensor and intrinsics, class definitions, input dimensions, inference backend, TensorRT/CUDA version, memory use, latency, checksum, training/evaluation scope and known failure cases.</p><h2 id="perception-packages" tabindex="-1">Perception packages <a class="header-anchor" href="#perception-packages" aria-label="Permalink to &quot;Perception packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Scope</th><th>Apollo Lite entry</th></tr></thead><tbody><tr><td>Ground detection</td><td>LiDAR ground service, ground detector, spatio-temporal ground detection and segmentation</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/ground_detector" target="_blank" rel="noreferrer">ground_detector</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/scene_manager/ground_service" target="_blank" rel="noreferrer">ground service</a></td></tr><tr><td>Obstacle detection</td><td>Camera, LiDAR, BEV and offline obstacle detection</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/obstacle" target="_blank" rel="noreferrer">Camera obstacle</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/lidar/lib/detector" target="_blank" rel="noreferrer">LiDAR detector</a></td></tr><tr><td>Tracking and fusion</td><td>OMT/OMT2, multi-LiDAR and probabilistic fusion</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/obstacle/tracker" target="_blank" rel="noreferrer">Tracking</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/fusion" target="_blank" rel="noreferrer">Fusion</a></td></tr><tr><td>Lane perception</td><td>UFLDv2, DarkSCNN, Denseline and lane calibration</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/lane" target="_blank" rel="noreferrer">Lane</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/lane" target="_blank" rel="noreferrer">Lane perception</a></td></tr><tr><td>Traffic-light perception</td><td>Detection, recognition, preprocessing and visualization</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/perception/camera/lib/traffic_light" target="_blank" rel="noreferrer">Traffic light</a></td></tr><tr><td>Localization</td><td>NDT, MSF, RTK and localization health monitoring</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/localization" target="_blank" rel="noreferrer">Localization</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/localization_health" target="_blank" rel="noreferrer">Localization health</a></td></tr></tbody></table><h2 id="planning-and-parking" tabindex="-1">Planning and parking <a class="header-anchor" href="#planning-and-parking" aria-label="Permalink to &quot;Planning and parking&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Scope</th><th>Apollo Lite entry</th></tr></thead><tbody><tr><td>Precision parking</td><td>Open-space planning, multi-gear parking search, curvature-constrained smoothing and collision checks</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/open_space_planning" target="_blank" rel="noreferrer">Open-space planning</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/planning/open_space/parking" target="_blank" rel="noreferrer">Parking planning</a></td></tr><tr><td>Mapless/open-space planning</td><td>Skeleton Corridor, Hybrid A*, trajectory planning, validation and safe degradation</td><td><a href="https://github.com/wheelos/apollo-lite/blob/main/modules/open_space_planning/README.md" target="_blank" rel="noreferrer">Open-space planning README</a></td></tr><tr><td>Reference-line planning</td><td>Lane following, traffic rules, scenario and mission planning</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/planning" target="_blank" rel="noreferrer">Planning</a></td></tr><tr><td>Routing and relative map</td><td>Route topology, relative maps and navigation modes</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/routing" target="_blank" rel="noreferrer">Routing</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/world_model/relative_map" target="_blank" rel="noreferrer">Relative map</a></td></tr></tbody></table><h2 id="calibration-and-control" tabindex="-1">Calibration and control <a class="header-anchor" href="#calibration-and-control" aria-label="Permalink to &quot;Calibration and control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Scope</th><th>Apollo Lite entry</th></tr></thead><tbody><tr><td>Vehicle dynamics calibration</td><td>Actuator calibration, lateral dynamics tests, plan generation, CyberRT recording and offline analysis</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/whl-dyn" target="_blank" rel="noreferrer">whl-dyn</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/wheelos-service/context/modules/tools/whl-dyn-open-loop-calibration-tool.md" target="_blank" rel="noreferrer">Tool guide</a></td></tr><tr><td>Longitudinal and lateral control</td><td>MPC, longitudinal control, lateral control, calibration tables and replay</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/control" target="_blank" rel="noreferrer">Control</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/modules/control/conf" target="_blank" rel="noreferrer">Control configuration</a></td></tr><tr><td>Sensor calibration</td><td>Camera, LiDAR, lane and coordinate-transform calibration</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/calibration" target="_blank" rel="noreferrer">Calibration</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/sensor_calibration.sh" target="_blank" rel="noreferrer">sensor_calibration.sh</a></td></tr></tbody></table><h2 id="engineering-tools" tabindex="-1">Engineering tools <a class="header-anchor" href="#engineering-tools" aria-label="Permalink to &quot;Engineering tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Entry</th></tr></thead><tbody><tr><td><code>whl-dyn</code></td><td>Dynamics calibration, test plans, data collection, offline metrics and Streamlit workbench</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/whl-dyn" target="_blank" rel="noreferrer">whl-dyn README</a></td></tr><tr><td><code>whl-debug</code></td><td>Controller debugging, online/offline data extraction and issue diagnosis</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-debug" target="_blank" rel="noreferrer">whl-debug</a></td></tr><tr><td><code>whl-tools</code></td><td>Camera segmentation, image publishing and lane-debug visualization</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-tools" target="_blank" rel="noreferrer">whl-tools</a></td></tr><tr><td><code>whl_toolbox</code></td><td>Point-cloud, SLAM, sensor and runtime-data visualization</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl_toolbox" target="_blank" rel="noreferrer">whl_toolbox</a></td></tr><tr><td><code>whl-can</code></td><td>CAN automation, static/dynamic cases and vehicle-interface validation</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-can" target="_blank" rel="noreferrer">whl-can</a></td></tr><tr><td><code>whl-mock</code></td><td>Mock publishing for routing, traffic-light and other inputs</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/tools/whl-mock" target="_blank" rel="noreferrer">whl-mock</a></td></tr><tr><td>Map tools</td><td>Map generation from Mobileye, XY and other sources; route topology generation</td><td><a href="https://github.com/wheelos/apollo-lite/tree/main/modules/map/tools" target="_blank" rel="noreferrer">Map tools</a> · <a href="https://github.com/wheelos/apollo-lite/tree/main/scripts" target="_blank" rel="noreferrer">Scripts</a></td></tr><tr><td>Recording and replay</td><td>CyberRT recording, message recording, map-data collection and replay</td><td><a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/recording_launcher.py" target="_blank" rel="noreferrer">recording_launcher.py</a> · <a href="https://github.com/wheelos/apollo-lite/blob/main/scripts/record_map_data.py" target="_blank" rel="noreferrer">record_map_data.py</a></td></tr></tbody></table><h2 id="wheelos-data-services" tabindex="-1">WheelOS data services <a class="header-anchor" href="#wheelos-data-services" aria-label="Permalink to &quot;WheelOS data services&quot;">​</a></h2><p>Vehicle data should not be scattered as raw files in the Git repository. The following service catalog is a planned product boundary; entries marked pending are not current public download links.</p><table tabindex="0"><thead><tr><th>Service</th><th>Intended users</th><th>Proposed capability</th><th>Current state</th></tr></thead><tbody><tr><td>Dataset catalog</td><td>Algorithm, calibration and test engineers</td><td>Search by vehicle, sensor, scenario and version; return dataset ID, time range, topics, format, size and permissions</td><td>Entry point pending</td></tr><tr><td>Raw recording service</td><td>Data and test engineers</td><td>CyberRT/MCAP upload, ranged download, resume, checksums and lifecycle management</td><td>Entry point pending</td></tr><tr><td>Annotation and sample service</td><td>Perception engineers</td><td>Sample selection, annotation versions, Lite export formats and train/validation freezing</td><td>Entry point pending</td></tr><tr><td>Replay and evaluation</td><td>Validation engineers</td><td>Select records, bind code/config, run offline replay and output metrics</td><td>Entry point pending</td></tr><tr><td>Model artifact service</td><td>Model and deployment engineers</td><td>Models, inference configuration, TensorRT engines, checksums and hardware/driver compatibility</td><td>Entry point pending</td></tr></tbody></table><p>APIs should expose <code>resource_id</code>, <code>version</code>, <code>source_commit</code>, <code>format</code>, <code>checksum</code>, <code>license</code>, <code>access</code>, <code>created_at</code> and <code>expires_at</code> so that downloads, replay and evidence records remain traceable.</p><h2 id="wheelos-map-services" tabindex="-1">WheelOS map services <a class="header-anchor" href="#wheelos-map-services" aria-label="Permalink to &quot;WheelOS map services&quot;">​</a></h2><p>Map services should provide versioned maps for localization, routing, perception ROI, open-space planning and precision parking rather than a single static archive.</p><table tabindex="0"><thead><tr><th>Service</th><th>Capability</th><th>Proposed content</th><th>Current state</th></tr></thead><tbody><tr><td>Map catalog</td><td>Discovery and version selection</td><td>Area, coordinate frame, coverage, version, update time, compatible vehicles and change history</td><td>Entry point pending</td></tr><tr><td>HD map download</td><td>Localization, routing and reference-line planning</td><td><code>base_map</code>, <code>routing_map</code>, <code>sim_map</code>, topology and generation metadata</td><td>Entry point pending</td></tr><tr><td>Parking-map service</td><td>Precision parking and open-space planning</td><td>Parking slots, lane boundaries, forbidden areas, target poses, ROI and scenario configuration</td><td>Entry point pending</td></tr><tr><td>Map validation and conversion</td><td>Pre-release validation</td><td>Format conversion, frame checks, topology checks, planning usability and diff reports</td><td>Entry point pending</td></tr></tbody></table><p>A map record should include coordinate frame, origin, projection, vehicle constraints, generator version, input-data date, coverage boundary, checksum and rollback version. Map versions must be linked to replay records, planning configuration and vehicle calibration.</p><h2 id="resource-catalog-rules" tabindex="-1">Resource-catalog rules <a class="header-anchor" href="#resource-catalog-rules" aria-label="Permalink to &quot;Resource-catalog rules&quot;">​</a></h2><ol><li>Build the catalog from actual capabilities in <code>modules/</code>, <code>whl-dyn/</code>, <code>scripts/</code> and <code>wheelos-service/</code>.</li><li>Separate models from runnable algorithm packages and tools.</li><li>Publish code through Git releases and data/maps through permissioned, versioned WheelOS services.</li><li>Organize entry points by task before module name.</li><li>Bind every download to an Apollo Lite commit, configuration, model, map, vehicle calibration and evaluation result.</li></ol>',27)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
